def max_gain(prices):
    best = -1
    lowest = prices[0]
    for x in prices[1:]:
        d = x - lowest
        if d > best:
            best = d
        if x < lowest:
            lowest = x
    if best <= 0:
        return -1
    return best


def main():
    prices = list(map(int, input().split()))
    print(max_gain(prices))


