class TNode:
    def __init__(self, v):
        self.val = v
        self.left = None
        self.right = None


def build_tree(tokens):
    it = iter(tokens)
    first = next(it, -1)
    if first == -1:
        return None
    root = TNode(first)
    q = [root]
    for node in q:
        l = next(it, -1)
        if l != -1:
            node.left = TNode(l)
            q.append(node.left)
        r = next(it, -1)
        if r != -1:
            node.right = TNode(r)
            q.append(node.right)
    return root


def find_node(root, x):
    if root is None:
        return None
    if root.val == x:
        return root
    found = find_node(root.left, x)
    if found is not None:
        return found
    return find_node(root.right, x)


def collect(root):
    if root is None:
        return 0
    return root.val + collect(root.left) + collect(root.right)


def subtree_sum(root, x):
    node = find_node(root, x)
    if node is None:
        return 0
    return collect(node)


def main():
    lines = read_lines()
    root = build_tree(list(map(int, lines[1].split())))
    x = int(lines[2])
    print(subtree_sum(root, x))


main()

