def read_graph():
    V, E = map(int, input().split())
    adj = {v: [] for v in range(V)}
    for _ in range(E):
        u, v = map(int, input().split())
        adj[u].append(v)
    return V, adj


def topo_order(adj):
    V = len(adj)
    indeg = {}
    for u in adj:
        indeg[u] = 0
    for u in adj:
        for v in adj[u]:
            indeg[v] += 1
    order = []
    placed = set()
    while len(order) < V:
        best = -1
        for v in range(V):
            if v not in placed and indeg[v] == 0:
                best = v
                break
        order.append(best)
        placed.add(best)
        for w in adj[best]:
            indeg[w] -= 1
    return order


def main():
    V, adj = read_graph()
    print(' '.join(map(str, topo_order(adj))))


main()

