import sys


class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None


def build_dll_chain(values):
    head = None
    tail = None
    for v in values:
        node = Node(v)
        node.prev = tail
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def build_singly(values):
    head = None
    tail = None
    for v in values:
        node = Node(v)
        if head is None:
            head = node
        else:
            tail.next = node
        tail = node
    return head


def tail_node(head):
    node = head
    while node.next is not None:
        node = node.next
    return node


def dll_forward(head):
    out = []
    node = head
    while node is not None:
        out.append(node.value)
        node = node.next
    return out


def dll_backward(head):
    node = tail_node(head)
    out = []
    while node is not None:
        out.append(node.value)
        node = node.prev
    return out


def build_circle(values):
    head = build_singly(values)
    tail = tail_node(head)
    tail.next = head
    return head


def circle_lap(head):
    out = [head.value]
    node = head.next
    while node is not head:
        out.append(node.value)
        node = node.next
    return out

def is_dll_circular(head):
    if head.prev is not None:
        return True
    node = head
    while node.next is not None:
        node = node.next
    return node.next is head


def main():
    sys.setrecursionlimit(100000)

    data = sys.stdin.read().split()
    n = int(data[0])
    values = list(map(int, data[1:1 + n]))
    c = int(data[1 + n])
    head = build_dll_chain(values)
    if c == 1:
        tail = tail_node(head)
        tail.next = head
        head.prev = tail
    print(is_dll_circular(head))


main()

import sys


def read_lines():
    return [ln.strip() for ln in sys.stdin.read().split('\n') if ln.strip() != '']


def circular_queue_ops(cap, ops):
    buf = [None] * cap
    head = 0
    count = 0
    res = []
    for op in ops:
        parts = op.split()
        if parts[0] == "enq":
            if count < cap:
                buf[(head + count) % cap] = int(parts[1])
                count += 1
        elif parts[0] == "deq":
            if count == 0:
                res.append("EMPTY")
            else:
                res.append(buf[head])
                head = (head + 1) % cap
                count -= 1
        else:
            res.append("EMPTY" if count == 0 else buf[head])
    return res


def main():
    lines = read_lines()
    cap = int(lines[0])
    ops = lines[2:]
    print('\n'.join(map(str, circular_queue_ops(cap, ops))))


