def shortest_distance(adj):
    n = len(adj)
    INF = float("inf")
    dist = {}
    for v in range(n):
        dist[v] = INF
    dist[0] = 0
    done = set()
    while len(done) < n:
        best = -1
        best_d = INF
        for v in range(n):
            if v not in done and dist[v] < best_d:
                best_d = dist[v]
                best = v
        if best == -1:
            break
        done.add(best)
        for v, w in adj[best]:
            if dist[best] + w < dist[v]:
                dist[v] = dist[best] + w
    if dist[n - 1] == INF:
        return -1
    return dist[n - 1]


def main():
    V, adj = read_graph()
    print(shortest_distance(adj))


