def binomial(n, k):
    row = []
    for i in range(n + 1):
        row.append([0] * (i + 1))
        row[i][0] = 1
        row[i][i] = 1
        for j in range(1, i):
            row[i][j] = row[i - 1][j - 1] + row[i - 1][j]
    return row[n][k]


