def minimum_swaps(values):
    a = values[:]
    n = len(a)
    ranks = {}
    for v in a:
        r = 0
        for w in a:
            if w < v:
                r += 1
        ranks[v] = r
    swaps = 0
    i = 0
    while i < n:
        j = ranks[a[i]]
        if j != i:
            a[i], a[j] = a[j], a[i]
            swaps += 1
        else:
            i += 1
    return swaps


