def max_loot(cash):
    n = len(cash)
    dp = []
    for i in range(n):
        dp.append(0)
    dp[0] = cash[0]
    if n > 1:
        dp[1] = cash[0] if cash[0] > cash[1] else cash[1]
        for i in range(2, n):
            best = cash[i] + dp[i - 2]
            if dp[i - 1] > best:
                best = dp[i - 1]
            dp[i] = best
    return dp[n - 1]


