from functools import lru_cache


@lru_cache(maxsize=None)
def steps_to_one(n):
    if n == 1:
        return 0
    best = steps_to_one(n - 1)
    if n % 2 == 0:
        two = steps_to_one(n // 2)
        if two < best:
            best = two
    if n % 3 == 0:
        three = steps_to_one(n // 3)
        if three < best:
            best = three
    return best + 1


def main():
    n = int(input())
    print(steps_to_one(n))


main()

