import sys


def occurrences_of(values, x):
    lo, hi = 0, len(values) - 1
    first = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == x:
            first = mid
            hi = mid - 1
        elif values[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    if first == -1:
        return 0
    lo, hi = first, len(values) - 1
    last = first
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == x:
            last = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return last - first + 1


