def print_order(jobs):
    urgent = deque()
    normal = deque()
    for job in jobs:
        name, prio = job.split()
        if prio == "1":
            urgent.append(name)
        else:
            normal.append(name)
    out = []
    while urgent:
        out.append(urgent.popleft())
    while normal:
        out.append(normal.popleft())
    return out


