def window_distincts(nums, k):
    freq = {}
    res = []
    for i, x in enumerate(nums):
        freq[x] = freq.get(x, 0) + 1
        if i >= k:
            y = nums[i - k]
            freq[y] -= 1
            if freq[y] == 0:
                del freq[y]
        if i >= k - 1:
            res.append(len(freq))
    return res


