def connected_answers(V, edges, queries):
    parent = []
    for v in range(V):
        parent.append(v)

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    for u, v in edges:
        ru = find(u)
        rv = find(v)
        if ru != rv:
            parent[ru] = rv
    answers = []
    for u, v in queries:
        answers.append(find(u) == find(v))
    return answers


def main():
    V, E = map(int, input().split())
    edges = []
    for _ in range(E):
        u, v = map(int, input().split())
        edges.append((u, v))
    Q = int(input())
    queries = []
    for _ in range(Q):
        u, v = map(int, input().split())
        queries.append((u, v))
    for ans in connected_answers(V, edges, queries):
        print(ans)


